'use client'

import * as React from 'react'
import { cn } from "@/lib/utils"
import { DayPicker } from 'react-day-picker'

import { buttonVariants } from './button'

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  components: userComponents,
  ...props
}: React.ComponentProps<typeof DayPicker>) {
  const defaultClassNames = {
    months: 'relative flex flex-col sm:flex-row gap-4',
    month: 'w-full',
    month_caption: 'relative mx-10 mb-1 flex h-9 items-center justify-center z-20',
    caption_label: 'text-sm font-medium',
    nav: 'absolute top-0 flex w-full justify-between z-10',
    button_previous: cn(
      buttonVariants({ variant: 'ghost' }),
      'size-9 text-muted-foreground/80 hover:text-foreground p-0'
    ),
    button_next: cn(
      buttonVariants({ variant: 'ghost' }),
      'size-9 text-muted-foreground/80 hover:text-foreground p-0'
    ),
    weekday: 'size-9 p-0 text-xs font-medium text-muted-foreground/80',
    day_button:
      'relative flex size-9 items-center justify-center whitespace-nowrap rounded-md p-0 text-foreground group-[[data-selected]:not(.range-middle)]:[transition-property:color,background-color,border-radius,box-shadow] group-[[data-selected]:not(.range-middle)]:duration-150 group-data-disabled:pointer-events-none focus-visible:z-10 hover:not-in-data-selected:bg-accent group-data-selected:bg-primary hover:not-in-data-selected:text-foreground group-data-selected:text-primary-foreground group-data-disabled:text-foreground/30 group-data-disabled:line-through group-data-outside:text-foreground/30 group-data-selected:group-data-outside:text-primary-foreground outline-none focus-visible:ring-ring/50 focus-visible:ring-[3px] group-[.range-start:not(.range-end)]:rounded-e-none group-[.range-end:not(.range-start)]:rounded-s-none group-[.range-middle]:rounded-none group-[.range-middle]:group-data-selected:bg-accent group-[.range-middle]:group-data-selected:text-foreground',
    day: 'group size-9 px-0 py-px text-sm',
    range_start: 'range-start',
    range_end: 'range-end',
    range_middle: 'range-middle',
    today:
      '*:after:pointer-events-none *:after:absolute *:after:bottom-1 *:after:start-1/2 *:after:z-10 *:after:size-[3px] *:after:-translate-x-1/2 *:after:rounded-full *:after:bg-primary [&[data-selected]:not(.range-middle)>*]:after:bg-background [&[data-disabled]>*]:after:bg-foreground/30 *:after:transition-colors',
    outside: 'text-muted-foreground data-selected:bg-accent/50 data-selected:text-muted-foreground',
    hidden: 'invisible',
    week_number: 'size-9 p-0 text-xs font-medium text-muted-foreground/80',
  }

  const mergedClassNames: typeof defaultClassNames = Object.keys(defaultClassNames).reduce(
    (acc, key) => ({
      ...acc,
      [key]: classNames?.[key as keyof typeof classNames]
        ? cn(
            defaultClassNames[key as keyof typeof defaultClassNames],
            classNames[key as keyof typeof classNames]
          )
        : defaultClassNames[key as keyof typeof defaultClassNames],
    }),
    {} as typeof defaultClassNames
  )

  const defaultComponents = {
    Chevron: (props: {
      className?: string
      size?: number
      disabled?: boolean
      orientation?: 'left' | 'right' | 'up' | 'down'
    }) => {
      if (props.orientation === 'left') {
        return (
          <svg
            width={16}
            height={16}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <path d="m15 18-6-6 6-6" />
          </svg>
        )
      }
      return (
        <svg
          width={16}
          height={16}
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <path d="m9 18 6-6-6-6" />
        </svg>
      )
    },
  }

  const mergedComponents = {
    ...defaultComponents,
    ...userComponents,
  }

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      data-slot="calendar"
      className={cn('w-fit', className)}
      classNames={mergedClassNames}
      components={mergedComponents}
      {...props}
    />
  )
}

export { Calendar }

import { computed } from "vue";
import { normalizeProps, useMachine } from "@zag-js/vue";
import { calendarConnect, calendarMachine } from "@/lib/utils";
import type { CalendarVueProps, CalendarVueValue, CalendarMode, CalendarRangeValue } from "@/lib/utils";
import { getLocalTimeZone } from "@internationalized/date";
import { parse as parseDateValue } from "@zag-js/date-picker";
import type { DateValue } from "@zag-js/date-picker";

export type UseCalendarProps = CalendarVueProps & {
    showOutsideDays?: boolean;
    numberOfMonths?: number;
    minDate?: string | Date;
    maxDate?: string | Date;
    isDateUnavailable?: (date: Date) => boolean;
};

type CalendarModelValue =
    | Date
    | {
        from?: Date;
        to?: Date;
    }
    | undefined;

export type UseCalendarEmits = {
    (e: "update:modelValue", value: CalendarModelValue): void;
    (e: "change", value: CalendarModelValue): void;
};

export function useCalendar(props: UseCalendarProps, emit: UseCalendarEmits) {
    const localTimeZone = getLocalTimeZone();
    const toCalendarDate = (input: string | Date) =>
        parseDateValue(
            input instanceof Date
                ? `${input.getFullYear()}-${String(input.getMonth() + 1).padStart(2, "0")}-${String(
                    input.getDate()
                ).padStart(2, "0")}`
                : input
        );

    const toDateValueArray = (value: CalendarVueValue | undefined, mode: CalendarMode) => {
        if (!value) return undefined;
        if (value instanceof Date) return [toCalendarDate(value)];

        const range = value as CalendarRangeValue;
        if (mode === "range") {
            const parsed: DateValue[] = [];
            if (range?.from) parsed.push(toCalendarDate(range.from));
            if (range?.to) parsed.push(toCalendarDate(range.to));
            return parsed.length ? parsed : undefined;
        }

        const fallback = range?.from ?? range?.to;
        return fallback ? [toCalendarDate(fallback)] : undefined;
    };

    const toModelValue = (values: DateValue[], mode: CalendarMode) => {
        if (mode === "range") {
            const from = values[0]?.toDate(localTimeZone);
            const to = values[1]?.toDate(localTimeZone);
            return from || to ? { from, to } : undefined;
        }
        return values[0]?.toDate(localTimeZone);
    };

    const machineProps = computed(() => {
        const controlledValue =
            props.modelValue !== undefined
                ? toDateValueArray(props.modelValue, props.mode || "single")
                : undefined;

        const defaultValue =
            props.modelValue === undefined
                ? toDateValueArray(props.defaultValue, props.mode || "single")
                : undefined;

        return {
            selectionMode: props.mode || "single",
            numOfMonths: props.numberOfMonths || 1,
            outsideDaySelectable: props.showOutsideDays ?? true,
            min: props.minDate ? toCalendarDate(props.minDate) : undefined,
            max: props.maxDate ? toCalendarDate(props.maxDate) : undefined,
            disabled: props.disabled,
            timeZone: localTimeZone,
            value: controlledValue,
            defaultValue,
            isDateUnavailable: props.isDateUnavailable
                ? (date: DateValue) => !!props.isDateUnavailable?.(date.toDate(localTimeZone))
                : undefined,
            onValueChange(details: { value: DateValue[] }) {
                const next = toModelValue(details.value, props.mode || "single");
                emit("update:modelValue", next);
                emit("change", next);
            },
        };
    });

    const service = useMachine(calendarMachine, machineProps);
    const api = computed(() => calendarConnect(service, normalizeProps));

    return {
        api,
        localTimeZone,
    };
}

import { cn } from '../utils'

Component({
  externalClasses: ['ext-class'],
  properties: {
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    className: '',
  },
  observers: {
    extClass: function (extClass) {
      this.setData({
        className: cn('w-fit', extClass),
      })
    },
  },
})
